// ── Resolve config, the same way 3/build/n8n reads its webhook secret ──
//
// KOYA_APP_URL and KOYA_TICK_KEY are used inside expression fields on the
// HTTP node below (its URL and its auth header). An expression like
// {{ $env.FOO || $vars.FOO }} looks like the obvious way to add a fallback,
// but it is not safe: touching $env THROWS on an instance where env access
// is blocked (true by default when self-hosted, and $env does not exist at
// all on n8n Cloud), and a throw inside an expression fails the node before
// the `||` ever gets a chance to fall through to $vars. Resolving both
// values here, in a Code node with the throw properly caught, is what makes
// the fallback actually work rather than only appearing to.
//
// KOYA_TICK_KEY fails CLOSED: a tick that cannot authenticate itself must
// not run silently as an unauthenticated request. KOYA_APP_URL is spelled
// out in the same error rather than defaulted, because a wrong guess here
// would tick a URL nobody intended and the failure would be far harder to
// trace than a clear message naming exactly what is missing.

function readVar(name) {
  try {
    if (typeof $env !== 'undefined' && $env && $env[name]) return String($env[name]);
  } catch (err) {
    // Env access is blocked on this instance. Not fatal — try Variables.
  }
  try {
    if (typeof $vars !== 'undefined' && $vars && $vars[name]) return String($vars[name]);
  } catch (err) {
    // Neither source is readable. Handled by the fail-closed check below.
  }
  return null;
}

const appUrl = readVar('KOYA_APP_URL');
const tickKey = readVar('KOYA_TICK_KEY');
const missing = [!appUrl && 'KOYA_APP_URL', !tickKey && 'KOYA_TICK_KEY'].filter(Boolean);

if (missing.length) {
  throw new Error(
    `${missing.join(' and ')} not readable on this n8n instance. Set as a Variable ` +
    '(Settings → Variables), or as an environment variable with ' +
    'N8N_BLOCK_ENV_ACCESS_IN_NODE=false. Refusing to tick the queue unauthenticated.');
}

return { json: { appUrl, tickKey } };

// ── Compose the Discord alert as plain markdown ──────────────────────
//
// The native Discord node's `content` field takes text, not the embeds
// array the previous httpRequest-based version built. Composing it here,
// in a Code node, is the same shape 3/build/n8n/koya-proposal-delivery.json
// uses for its "Build failure notice" step: format upstream, post downstream.

const body = $json.body || {};
const config = $('Resolve config').first().json;

const swept = (body.swept || []).map((s) =>
  `⚠️ recovered a stalled request from \`${s.from}\` → \`${s.to}\` — something crashed ` +
  `mid-run: ${config.appUrl}/requests/${s.id}`);

const details = (body.details || [])
  .filter((d) => d.state !== 'sent' && d.state !== 'queued_manual')
  .map((d) =>
    `• **${d.channel}** → ${d.state}${d.code ? ` (\`${d.code}\`)` : ''} ` +
    `${config.appUrl}/requests/${d.requestId}`);

const content = [
  `🔴 **Publishing queue: ${body.summary || 'needs attention'}**`,
  ...swept,
  ...details,
].join('\n').slice(0, 3900);

return { json: { content } };
